import{c as t,Q as i,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"ChatGPT-5.5 Cross-Vendor Independent Review of Fusion Architecture","description":"","frontmatter":{"title":"ChatGPT-5.5 Cross-Vendor Independent Review of Fusion Architecture","date":"2026-07-09T00:00:00.000Z","status":"done","method":"Independent fresh-context review from a non-Anthropic, non-Cognition reasoning baseline. Mechanical checks executed before prose findings.","parent-artifacts":["research/reports/2026-07-09-fusion-architecture-design-plan.md","research/reports/2026-07-09-fusion-glm-architecture-validation.md","research/reports/2026-07-09-fusion-glm-factory-phase2-config.md","research/reports/2026-07-09-fusion-kimi-token-simulation.md","research/reports/2026-07-09-fusion-kimi-agents-md-protocol-draft.md"],"reviewer":"ChatGPT-5.5 (frontier tier, cross-vendor, fresh-context)","scope":"Full Fusion architecture design + 4 sub-reports + source material","type":"cross-vendor-adversarial-review"},"headers":[],"relativePath":"research/reports/2026-07-09-cross-review-chatgpt-cross-vendor.md","filePath":"research/reports/2026-07-09-cross-review-chatgpt-cross-vendor.md","lastUpdated":1785909234000}'),n={name:"research/reports/2026-07-09-cross-review-chatgpt-cross-vendor.md"};function a(r,e,d,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="chatgpt-5-5-cross-vendor-independent-review-of-fusion-architecture" tabindex="-1">ChatGPT-5.5 Cross-Vendor Independent Review of Fusion Architecture <a class="header-anchor" href="#chatgpt-5-5-cross-vendor-independent-review-of-fusion-architecture" aria-label="Permalink to &quot;ChatGPT-5.5 Cross-Vendor Independent Review of Fusion Architecture&quot;">​</a></h1><h2 id="reviewer-context" tabindex="-1">Reviewer Context <a class="header-anchor" href="#reviewer-context" aria-label="Permalink to &quot;Reviewer Context&quot;">​</a></h2><ul><li><strong>Model</strong>: ChatGPT-5.5 (frontier tier, cross-vendor)</li><li><strong>Mode</strong>: Independent, fresh context — no shared ecosystem bias with Claude Code / Anthropic / Cognition</li><li><strong>Scope</strong>: Full Fusion architecture design plan + 4 sub-reports + AGENTS.md + delegation-protocol.md</li><li><strong>Stance</strong>: Adversarial-by-default (per workspace <code>subagent-strategy.md</code> &quot;對抗立場預設&quot;); verdict ≠ evidence</li><li><strong>What I am NOT</strong>: I am not reviewing to validate the design. I am reviewing to find what same-ecosystem reviewers (Claude, GLM, Kimi — all of whom share the Anthropic-adjacent or open-source-Fusion framing) would systematically miss.</li></ul><hr><h2 id="a-vendor-neutrality-audit" tabindex="-1">A. Vendor Neutrality Audit <a class="header-anchor" href="#a-vendor-neutrality-audit" aria-label="Permalink to &quot;A. Vendor Neutrality Audit&quot;">​</a></h2><h3 id="a1-the-claude-code-path-vs-factory-path-framing-is-a-false-dichotomy" tabindex="-1">A1. The &quot;Claude Code path vs Factory path&quot; framing is a false dichotomy <a class="header-anchor" href="#a1-the-claude-code-path-vs-factory-path-framing-is-a-false-dichotomy" aria-label="Permalink to &quot;A1. The &quot;Claude Code path vs Factory path&quot; framing is a false dichotomy&quot;">​</a></h3><p>The design plan §2.3-§2.4 presents exactly two implementation paths: Claude Code (Phase 1-2) and Factory Droid (Phase 1-3). A genuinely vendor-neutral design would acknowledge at least three additional paths that this framing excludes:</p><ol><li><strong>Direct API path</strong> (no harness at all): A pure-API user could implement the Sidekick pattern with two parallel API clients maintaining independent cached prefixes — no Claude Code, no Factory Droid. The design&#39;s §2.5 &quot;AGENTS.md Fusion Protocol&quot; claims to be &quot;harness-neutral&quot; but then immediately grounds all concrete steps in either Claude Code sub-agent spawn or Factory Session API PATCH. A pure-API user reading this design gets an abstract protocol and zero executable steps.</li><li><strong>Alternative harness path</strong> (Cursor, Codex, Aider, Continue): The AGENTS.md §1 &quot;Portability note (MHF)&quot; itself admits &quot;switching to Codex/Cursor = rebuild enforcement layer.&quot; The Fusion design silently inherits this limitation — its &quot;harness-neutral&quot; claim is only as portable as the two harnesses it explicitly targets.</li><li><strong>Orchestration-layer path</strong> (LangGraph, DSPy, custom router): The &quot;Fusion Router (L0)&quot; in §2.2 is described as a &quot;lightweight classifier&quot; but its implementation is left entirely unspecified. A vendor-neutral design would at minimum name the abstraction boundary (is the router a model call? a rule engine? a hook?).</li></ol><p><strong>Verdict on neutrality</strong>: The design is &quot;bi-harness-neutral&quot; (Claude Code + Factory), not vendor-neutral. It is Anthropic-flavored throughout — every concrete pricing figure, every cache threshold, every model ID comes from <code>model-profiles.md</code> which is 100% Anthropic (the file itself notes &quot;4 檔位全 Anthropic = 監管單點失效&quot;). A reviewer from OpenAI, Mistral, or a self-hosted shop would not recognize this as their architecture.</p><h3 id="a2-the-factory-session-api-patch-capability-is-partially-verified-not-fully" tabindex="-1">A2. The Factory Session API PATCH capability is partially verified, not fully <a class="header-anchor" href="#a2-the-factory-session-api-patch-capability-is-partially-verified-not-fully" aria-label="Permalink to &quot;A2. The Factory Session API PATCH capability is partially verified, not fully&quot;">​</a></h3><p>The GLM Phase 2 config report (D6 verification) is the strongest part of the submission — it actually catches that <code>providerLock</code> is <strong>not</strong> a settable CLI switch and that <code>providerLockTimestamp</code>&#39;s semantics are undocumented. This is exactly the kind of assumption-challenging a cross-vendor reviewer expects, and GLM-5.2 performed it well.</p><p>However, two API-behavior assumptions remain unchallenged that a non-Anthropic vendor would press harder on:</p><ol><li><p><strong>&quot;compaction 本就觸發 cache 失效,因此順便換模型成為零額外 cache 懲罰&quot;</strong> (design §1.1, §2.2 L3). This is the <strong>load-bearing assumption</strong> of the entire Fusion architecture — the claim that model switching at compaction time is &quot;free.&quot; But this is asserted as a direct port of Cognition&#39;s Devin Fusion claim. Factory&#39;s <code>compactionModel</code> API field lets you <em>set</em> a different compaction model; it does <strong>not</strong> guarantee that switching the <em>main session model</em> mid-session (via PATCH <code>model</code>) preserves cache across the compaction boundary. The design conflates &quot;compaction invalidates cache anyway&quot; (true) with &quot;switching model at compaction is zero-penalty&quot; (only true if the new model&#39;s cache prefix is compatible with the surviving post-compaction context). A non-Anthropic vendor would ask: <em>does Factory&#39;s post-compaction context survive a model switch intact, or does the new model re-process the compacted summary from scratch?</em> The design does not answer this.</p></li><li><p><strong><code>compactionThresholdCheckEnabled: true</code> as the &quot;detect compaction trigger&quot; precondition</strong> (Phase 3). The design assumes setting this flag gives you a reliable signal to PATCH the model. But the flag&#39;s name suggests it <em>checks</em> the threshold, not that it <em>emits an event</em> you can hook. If it&#39;s a check (poll), you need a polling loop; if it&#39;s an event, you need a webhook. The Phase 3 pseudo-code (&quot;1. 偵測 compaction 觸發 → 2. PATCH session&quot;) skips the detection mechanism entirely.</p></li></ol><h3 id="a3-the-claude-code-path-sub-agent-spawn-devin-fusion-sidekick" tabindex="-1">A3. The &quot;Claude Code path&quot; sub-agent spawn ≠ Devin Fusion sidekick <a class="header-anchor" href="#a3-the-claude-code-path-sub-agent-spawn-devin-fusion-sidekick" aria-label="Permalink to &quot;A3. The &quot;Claude Code path&quot; sub-agent spawn ≠ Devin Fusion sidekick&quot;">​</a></h3><p>A subtle but critical conflation: Devin Fusion&#39;s sidekick maintains <strong>persistent cached context</strong> across many task delegations. The design&#39;s Claude Code Phase 1 uses <strong>one-shot sub-agent spawn</strong> (each spawn = fresh context). The GLM validation report correctly flags this (optimization item 4: ⚠️ needs modification) and the design plan §2.3 admits &quot;不是真正的 cache 持久化.&quot; So the architecture&#39;s own documentation acknowledges that <strong>the Claude Code path does not actually implement Fusion</strong> — it implements a degraded approximation. The -35.2% savings figure is computed assuming Phase 2/Factory persistent sidekick (token simulation §5 limitation 4), not the Phase 1 reality. This is a bait-and-switch risk: the headline number describes Phase 2+, but the &quot;zero-code-change&quot; claim describes Phase 1.</p><hr><h2 id="b-open-source-model-reliability" tabindex="-1">B. Open-Source Model Reliability <a class="header-anchor" href="#b-open-source-model-reliability" aria-label="Permalink to &quot;B. Open-Source Model Reliability&quot;">​</a></h2><h3 id="b1-glm-5-2-and-kimi-k2-7-as-sidekicks-—-reliability-assumptions-are-untested" tabindex="-1">B1. GLM-5.2 and Kimi K2.7 as sidekicks — reliability assumptions are untested <a class="header-anchor" href="#b1-glm-5-2-and-kimi-k2-7-as-sidekicks-—-reliability-assumptions-are-untested" aria-label="Permalink to &quot;B1. GLM-5.2 and Kimi K2.7 as sidekicks — reliability assumptions are untested&quot;">​</a></h3><p>The design proposes GLM-5.2 (ceiling-tier open-source) and Kimi K2.7 (quality-tier open-source) as sidekick candidates (§4.1). The supporting evidence is benchmark-adjacent: GLM-5.2 &quot;SWE-bench Pro 62.1% 接近 Opus&quot; and Kimi &quot;1000 tok/s + code 特化.&quot; But:</p><ol><li><strong>No workspace-internal eval exists for either model as a sidekick.</strong> The <code>model-profiles.md</code> §1 explicitly labels non-Claude models as &quot;未知=當最高處理&quot; (unknown = treat as highest tier). The design proposes routing <em>mechanical</em> tasks to these models, but &quot;mechanical&quot; tasks (grep, batch edit, test execution) are exactly where a subtly-wrong model does the most silent damage — a wrong grep pattern misses a security-relevant file, and nobody notices until production.</li><li><strong>The design&#39;s own §3.3 mechanism 5 (&quot;跨模型互查: GPT-5.5 複查 Fable 5 仍能抓到遺漏&quot;)</strong> is cited as evidence that cross-model review catches errors. But this is a <em>review</em> scenario (verdict on completed work), not a <em>execution</em> scenario (sidekick producing the work). The evidence does not transfer. A sidekick that produces subtly wrong mechanical output is not the same as a reviewer that misses a subtle error in someone else&#39;s work.</li></ol><h3 id="b2-eval-hack-risk-is-named-but-has-no-concrete-mitigation" tabindex="-1">B2. &quot;eval-hack risk&quot; is named but has no concrete mitigation <a class="header-anchor" href="#b2-eval-hack-risk-is-named-but-has-no-concrete-mitigation" aria-label="Permalink to &quot;B2. &quot;eval-hack risk&quot; is named but has no concrete mitigation&quot;">​</a></h3><p>Design §6 risk 4 names &quot;開源模型 eval-hack 風險未知&quot; and §3.3 mechanism 3 says &quot;檔位越高驗證越嚴.&quot; But:</p><ul><li><strong>No definition of &quot;eval-hack&quot; in this context.</strong> Does it mean the model has been trained on the benchmark (contamination)? Does it mean the model produces output that <em>looks</em> correct to a weak verifier but isn&#39;t? The design uses the term as if it&#39;s self-evident.</li><li><strong>No concrete detection mechanism.</strong> &quot;檔位越高驗證越嚴&quot; is a <em>policy</em>, not a <em>mechanism</em>. What is the mechanical check that distinguishes &quot;sidekick output is correct&quot; from &quot;sidekick output passes a weak gate&quot;? The delegation-protocol.md §6 says &quot;cost 產出 → parent 逐項覆核&quot; — but &quot;逐項覆核&quot; (item-by-item review) by the main agent is itself a cost (see §D2 below) and is only as good as the main agent&#39;s attention budget.</li><li><strong>The token simulation&#39;s quality column says &quot;維持/提升&quot; for tasks 3 and 5</strong> (where sidekick does mechanical work). This is an assertion, not a measured result. No task in the simulation has been actually run with a GLM/Kimi sidekick and verified.</li></ul><h3 id="b3-sidekick-failure-→-immediate-upgrade-no-retry-is-insufficient-for-partial-failures" tabindex="-1">B3. &quot;Sidekick failure → immediate upgrade, no retry&quot; is insufficient for partial failures <a class="header-anchor" href="#b3-sidekick-failure-→-immediate-upgrade-no-retry-is-insufficient-for-partial-failures" aria-label="Permalink to &quot;B3. &quot;Sidekick failure → immediate upgrade, no retry&quot; is insufficient for partial failures&quot;">​</a></h3><p>Delegation-protocol.md §6 and the design&#39;s Layer 4 say &quot;Sidekick 失敗 1 次即升級（cost → quality）,不重試.&quot; This handles <strong>crash failures</strong> (syntax error, tool exception, empty output) but is silent on <strong>partial failures</strong>:</p><ul><li><strong>Correct syntax, wrong logic</strong>: A sidekick produces a grep that runs successfully but uses a pattern that misses 3 of 10 relevant files. No exception is thrown. The &quot;failure&quot; signal never fires. The main agent&#39;s &quot;機械重驗&quot; must independently re-run the grep with a <em>different</em> pattern to detect this — but the design does not specify that the verification uses an <em>orthogonal</em> method, just that it &quot;機械重驗.&quot;</li><li><strong>Correct output, wrong scope</strong>: A sidekick edits the right function but in the wrong file (e.g., a similarly-named file in a different module). The diff looks valid. The main agent&#39;s review must know which file was <em>intended</em> — but if the main agent delegated because it didn&#39;t want to read the files, it may not catch the scope error.</li><li><strong>Plausible hallucination</strong>: An open-source sidekick summarizing a research paper could hallucinate a citation that looks real. The design&#39;s §3.3 &quot;Source-Verify gate&quot; is mentioned for task 3 but not mechanically specified — it&#39;s a named gate, not a defined check.</li></ul><p>The &quot;no retry&quot; rule optimizes for the failure mode where retrying wastes tokens. It does not address the failure mode where <em>there is no failure signal at all.</em> For open-source sidekicks with unknown reliability profiles, the partial-failure gap is the dominant risk.</p><hr><h2 id="c-devin-fusion-source-dependency" tabindex="-1">C. Devin Fusion Source Dependency <a class="header-anchor" href="#c-devin-fusion-source-dependency" aria-label="Permalink to &quot;C. Devin Fusion Source Dependency&quot;">​</a></h2><h3 id="c1-single-source-dependency-on-cognition-s-blog-—-confirmed" tabindex="-1">C1. Single-source dependency on Cognition&#39;s blog — confirmed <a class="header-anchor" href="#c1-single-source-dependency-on-cognition-s-blog-—-confirmed" aria-label="Permalink to &quot;C1. Single-source dependency on Cognition&#39;s blog — confirmed&quot;">​</a></h3><p>The entire architecture derives from one Cognition blog post (2026-06-29). Mechanical verification:</p><ul><li>The scored article (<code>research/ai-articles/scored/2026-07-02-cognition-devin-fusion-sidekick-routing.md</code>) itself rates evidence quality <strong>6/10</strong> with the note &quot;廠商自報 benchmark，非第三方驗證&quot; (vendor self-reported, not third-party verified).</li><li>WebSearch for independent verification returns <strong>only Cognition&#39;s own channels</strong> (cognition.com, @cognition on X, Jeff Wang&#39;s post, Reddit reposts of the blog, digg.com summary, codenewsletter.ai summary). <strong>Zero independent third-party reproductions</strong> of the 35% / 41% / 88% figures exist as of 2026-07-09.</li><li>The zenml.io LLMops database entry is a <em>description</em> of Cognition&#39;s approach, not an independent benchmark.</li></ul><p><strong>Implication</strong>: The -35.2% headline is a number derived from a design <em>inspired by</em> a vendor&#39;s <em>self-reported</em> number, simulated on a <em>different</em> workspace&#39;s <em>estimated</em> task distribution. It is three levels of inference removed from any independently measured result. The design plan §6 risk 2 acknowledges &quot;43% 為廠商自報&quot; for Factory Router but does <strong>not</strong> apply the same caveat to the Devin Fusion 35-41% figures that anchor the entire architecture&#39;s value proposition.</p><h3 id="c2-the-88-fully-automated-merged-prs-figure-is-devin-specific-not-reproducible" tabindex="-1">C2. The 88% &quot;fully automated merged PRs&quot; figure is Devin-specific, not reproducible <a class="header-anchor" href="#c2-the-88-fully-automated-merged-prs-figure-is-devin-specific-not-reproducible" aria-label="Permalink to &quot;C2. The 88% &quot;fully automated merged PRs&quot; figure is Devin-specific, not reproducible&quot;">​</a></h3><p>The 88% figure measures <em>Devin&#39;s</em> merged PRs under <em>Devin&#39;s</em> Fusion routing on <em>Devin&#39;s</em> task distribution. The token simulation §3.2 shows this workspace&#39;s estimated task distribution is: 40% single-file-small-change (0% savings), 25% cross-module refactor (-36% cost increase), 20% deep research (+37%), 5% security review (-18%), 10% large migration (+53%). The cost-weighted average of <strong>-35.2%</strong> is <strong>entirely driven by the 10% large-migration task type</strong> (which contributes -29.7% of the -35.2% total). Remove large migrations from the workload, and Fusion is a net <strong>cost increase</strong> (+2.8% frequency-weighted, per the simulation&#39;s own §3.2).</p><p><strong>This is the single most important finding a cross-vendor reviewer can surface</strong>: The -35.2% savings is not a property of the Fusion architecture. It is a property of a workload that happens to contain a high proportion of mechanically-amenable large migrations. A workspace without large migrations (most SRE/ops workspaces, most product codebases) would see Fusion <em>increase</em> costs. The design presents -35.2% as if it generalizes; it does not.</p><h3 id="c3-the-frontiercode-57-6-vs-57-0-quality-claim-is-within-noise" tabindex="-1">C3. The FrontierCode 57.6 vs 57.0 quality claim is within noise <a class="header-anchor" href="#c3-the-frontiercode-57-6-vs-57-0-quality-claim-is-within-noise" aria-label="Permalink to &quot;C3. The FrontierCode 57.6 vs 57.0 quality claim is within noise&quot;">​</a></h3><p>The design cites &quot;FrontierCode 分數維持 frontier-level（57.6 vs 純 Fable 5 的 57.0）&quot; as evidence that quality is maintained. A 0.6-point difference on a benchmark with unknown variance is <strong>not evidence of maintained quality</strong> — it is consistent with noise. A cross-vendor reviewer would require either (a) the benchmark&#39;s reported variance / confidence interval, or (b) multiple runs. The design provides neither. The claim &quot;維持 frontier-level&quot; is reasonable but the specific 57.6-vs-57.0 framing overstates the precision of the evidence.</p><hr><h2 id="d-cost-model-reality-check" tabindex="-1">D. Cost Model Reality Check <a class="header-anchor" href="#d-cost-model-reality-check" aria-label="Permalink to &quot;D. Cost Model Reality Check&quot;">​</a></h2><h3 id="d1-the-35-2-math-is-mechanically-correct-but-built-on-fragile-assumptions" tabindex="-1">D1. The -35.2% math is mechanically correct but built on fragile assumptions <a class="header-anchor" href="#d1-the-35-2-math-is-mechanically-correct-but-built-on-fragile-assumptions" aria-label="Permalink to &quot;D1. The -35.2% math is mechanically correct but built on fragile assumptions&quot;">​</a></h3><p><strong>Mechanical verification of the cost arithmetic</strong> (executed via Python):</p><table tabindex="0"><thead><tr><th>Task</th><th>Reported existing</th><th>Calculated existing</th><th>Reported fusion</th><th>Calculated fusion</th><th>Reported savings</th><th>Calculated savings</th></tr></thead><tbody><tr><td>3 (deep research)</td><td>$0.4613</td><td>$0.4613 ✅</td><td>$0.2925</td><td>$0.2925 ✅</td><td>37%</td><td>36.6% (rounds to 37%) ✅</td></tr><tr><td>5 (large migration)</td><td>$1.536</td><td>$1.5360 ✅</td><td>$0.729</td><td>$0.7290 ✅</td><td>53%</td><td>52.5% (rounds to 53%) ✅</td></tr></tbody></table><p>The arithmetic is internally consistent. The pricing baseline (Haiku $1/$5, Sonnet $3/$15, Opus $5/$25, Fable $10/$50) matches <code>model-profiles.md</code> §0/§2.3. The 1.35x ceiling tokenizer factor is documented in §2.3. <strong>The math checks out.</strong> The problem is not the math; it is the inputs:</p><ol><li><strong>Token estimates are &quot;量級近似&quot; (order-of-magnitude approximations)</strong> — the simulation&#39;s own §5 limitation 1 admits this. No <code>count_tokens</code> was run. CJK inflation (1.3-2.3x per §2.5) is not applied despite the workspace operating in 繁體中文. This means the input token estimates are likely <strong>understated by 30-130%</strong> for this workspace&#39;s actual language mix, which would shift the cost-weighted savings figure.</li><li><strong>Task frequency weights are &quot;粗估&quot; (rough estimates)</strong> — §3.2 and §5 limitation 3 admit the 40/25/20/5/10 weights are subjective. The -35.2% figure is acutely sensitive to the large-migration weight: at 10% weight it&#39;s -35.2%; at 5% weight it would be ~-17%; at 0% it&#39;s +2.8%. The design does not run <code>evolution/cost-log.jsonl</code> to get real weights, despite the file existing.</li><li><strong>The cost-weighted vs frequency-weighted gap is buried</strong>: §3.4 shows frequency-weighted = +2.8% (cost <em>increase</em>) vs cost-weighted = -35.2% (savings). The headline uses cost-weighted. A vendor-neutral reviewer would headline <strong>both</strong> numbers and explain that the choice of weighting is a judgment call, not a settled fact.</li></ol><h3 id="d2-the-cost-of-verification-is-not-included-in-the-savings-figure" tabindex="-1">D2. The cost of verification is not included in the savings figure <a class="header-anchor" href="#d2-the-cost-of-verification-is-not-included-in-the-savings-figure" aria-label="Permalink to &quot;D2. The cost of verification is not included in the savings figure&quot;">​</a></h3><p>The design says &quot;sidekick output must be mechanically re-verified by main agent&quot; (§3.3 mechanism 1, delegation-protocol.md §6). This verification has a cost:</p><ul><li>delegation-protocol.md §6: &quot;cost 產出 → parent 逐項覆核&quot; (item-by-item review).</li><li>For task 5 (large migration, 16 PRs), the main agent (ceiling, $5/$25) must review 16 PRs of sidekick (cost) output. The simulation&#39;s Fusion cost for task 5 ($0.729) <strong>already includes</strong> main agent review tokens (main_out 3,000 for &quot;編排決策&quot;), but this is characterized as orchestration, not as the full item-by-item verification of 16 PRs of mechanical edits. If the main agent must read 16 PRs × ~50 lines × 8 tokens/line = 6,400 input tokens of diffs <em>at ceiling pricing</em> to verify them, that&#39;s 6,400 × 1.35 × $5/1M = $0.043 — small for task 5 but proportionally large for the smaller tasks where it&#39;s omitted.</li><li>For task 3 (deep research), the main agent must &quot;機械重驗引用來源&quot; (mechanically re-verify citation sources). Re-verifying 5 WebSearch citations means 5 additional searches + 5 reads, which is not in the Fusion cost column. This is an <strong>omitted verification cost</strong>.</li></ul><p><strong>Net effect</strong>: The -35.2% is an <em>upper bound</em> on savings, not a net figure. A more honest accounting would subtract verification overhead, which would compress the savings on the high-saving tasks (3, 5) and deepen the cost increase on the negative-saving tasks (2, 4).</p><h3 id="d3-the-36-cost-for-cross-module-refactor-is-a-real-architectural-overhead-not-a-tradeoff" tabindex="-1">D3. The +36% cost for cross-module refactor is a real architectural overhead, not a tradeoff <a class="header-anchor" href="#d3-the-36-cost-for-cross-module-refactor-is-a-real-architectural-overhead-not-a-tradeoff" aria-label="Permalink to &quot;D3. The +36% cost for cross-module refactor is a real architectural overhead, not a tradeoff&quot;">​</a></h3><p>Task 2 (cross-module refactor, 6-9 files) shows Fusion costs <strong>+36%</strong> more than the existing architecture. The simulation attributes this to &quot;ceiling 升級 + sidekick overhead.&quot; A cross-vendor reading: <strong>Fusion adds overhead for exactly the task type that is most representative of day-to-day engineering work</strong> (cross-module interface changes). The design frames this as &quot;品質換成本&quot; (quality for cost), but:</p><ul><li>The quality benefit (&quot;ceiling 規劃 + §6 機械重驗&quot;) is asserted, not measured (see §B2).</li><li>The existing architecture already routes 6-9 file tasks to quality tier (Sonnet 5), which the workspace&#39;s own model-profiles.md §2.3 notes is the &quot;標準工作馬&quot; (standard workhorse) — i.e., already a reasonable quality level.</li><li>Upgrading the main agent to ceiling (Opus 4.8, $5/$25, with 1.35x tokenizer penalty) for a task that Sonnet 5 handles well is <strong>over-engineering the planning layer</strong>. The design&#39;s §3.2 Layer 1 says &quot;標準任務 → quality 檔,&quot; but the Fusion architecture violates its own routing rule by defaulting the main agent to ceiling for all non-T0 tasks.</li></ul><p><strong>This is an architectural self-contradiction</strong>: the Fusion design&#39;s main-agent-is-always-ceiling default conflicts with the workspace&#39;s existing &quot;依位置數路由&quot; (route by file count) principle, which deliberately uses quality tier for 2-9 file tasks. Fusion doesn&#39;t preserve the existing routing intelligence; it replaces it with a cruder &quot;main = ceiling, sidekick = cost&quot; binary.</p><h3 id="d4-router-overhead-and-orchestration-tax-are-not-modeled" tabindex="-1">D4. Router overhead and orchestration tax are not modeled <a class="header-anchor" href="#d4-router-overhead-and-orchestration-tax-are-not-modeled" aria-label="Permalink to &quot;D4. Router overhead and orchestration tax are not modeled&quot;">​</a></h3><p>The &quot;Fusion Router (L0)&quot; classifier is described but its cost is never included in any simulation. If the router is a model call (even a cheap one), it runs on every task. If it&#39;s a rule engine, it has maintenance cost. The -35.2% assumes the router is free. Additionally, the simulation §5 limitation 5 admits &quot;未計 session overhead&quot; (session init / auto-load / hook execution / handoff parsing), noting &quot;實際節省會被 overhead 侵蝕, 尤其任務 1.&quot; This overhead is documented to be <strong>76.2k tokens for cost tier, 73.9k for quality</strong> (cited as &quot;O9&quot;) — which is larger than the entire input token budget for tasks 1 and 2. For task 1 (single-file change), the overhead alone dwarfs the task cost, making the 0% savings figure misleading (it should be negative when overhead is included).</p><hr><h2 id="e-missing-perspectives" tabindex="-1">E. Missing Perspectives <a class="header-anchor" href="#e-missing-perspectives" aria-label="Permalink to &quot;E. Missing Perspectives&quot;">​</a></h2><h3 id="e1-pure-api-user-perspective-design-is-not-relevant-to-them" tabindex="-1">E1. Pure-API user perspective: design is not relevant to them <a class="header-anchor" href="#e1-pure-api-user-perspective-design-is-not-relevant-to-them" aria-label="Permalink to &quot;E1. Pure-API user perspective: design is not relevant to them&quot;">​</a></h3><p>A pure-API user (no Claude Code, no Factory) gets from this design:</p><ul><li>An abstract 4-layer architecture diagram (§2.2) they could in principle implement.</li><li>An AGENTS.md Protocol draft (1077 bytes) that is too abstract to guide implementation (see §F2).</li><li>Zero concrete API patterns for implementing the Sidekick pattern with two parallel cached clients.</li></ul><p>The design is relevant to them only as <em>inspiration</em>. For execution, they would need to design their own router, their own cache-prefix management, their own compaction trigger detection — none of which the design specifies at the API level. <strong>The design&#39;s &quot;harness-neutral&quot; claim does not survive contact with a pure-API reader.</strong></p><h3 id="e2-multi-tenant-scenarios-design-is-single-user-single-session-oriented" tabindex="-1">E2. Multi-tenant scenarios: design is single-user/single-session oriented <a class="header-anchor" href="#e2-multi-tenant-scenarios-design-is-single-user-single-session-oriented" aria-label="Permalink to &quot;E2. Multi-tenant scenarios: design is single-user/single-session oriented&quot;">​</a></h3><p>Every simulation assumes a single user, single session, single main agent. There is no discussion of:</p><ul><li><strong>Concurrent sessions sharing a sidekick pool</strong> (could a sidekick serve multiple main agents? the design implies 1:1).</li><li><strong>Tenant isolation</strong> (if multiple users&#39; sidekicks run on shared infrastructure, does the cached context bleed?).</li><li><strong>Cost attribution</strong> (Factory&#39;s <code>childInclusiveTokenUsageBySessionId</code> is per-session, but a multi-tenant deployment would need per-tenant aggregation — not discussed).</li><li><strong>Rate limits</strong> (open-source sidekicks via BYOK may have provider rate limits that constrain parallelism; the 16-PR parallel migration in task 5 assumes no rate-limit binding).</li></ul><p>For a workspace owner this is fine (single-user). For anyone considering this as a <em>general</em> architecture, it&#39;s a gap.</p><h3 id="e3-latency-entirely-unaddressed" tabindex="-1">E3. Latency: entirely unaddressed <a class="header-anchor" href="#e3-latency-entirely-unaddressed" aria-label="Permalink to &quot;E3. Latency: entirely unaddressed&quot;">​</a></h3><p>The design optimizes for cost and claims quality is maintained. It says nothing about latency. But:</p><ul><li><strong>Model switching has latency</strong>: a PATCH to switch models mid-session, plus the new model&#39;s cold-start (cache miss on the new model&#39;s prefix), adds wall-clock time. The design claims &quot;零 cache 懲罰&quot; for compaction-time switches, but cache <em>miss</em> ≠ zero latency — the new model still has to process the compacted context.</li><li><strong>Sidekick round-trip latency</strong>: spawning a sub-agent (Claude Code) or PATCHing a session (Factory) + sidekick execution + report-back adds a round-trip the existing architecture (main agent does it inline) does not have. For task 1 (single-file change), the sidekick round-trip latency would likely exceed the inline execution time, which is why the design correctly excludes T0 tasks from sidekick routing — but this latency reasoning is never stated, only the cost reasoning.</li><li><strong>Parallel sidekick latency for task 5</strong>: 16 PRs in parallel assumes the sidekick infrastructure can actually run 16 concurrent executions. If it can&#39;t (rate limits, concurrency caps), the 53% savings figure is unreachable.</li></ul><p>A cross-vendor reviewer from a latency-sensitive domain (real-time, on-call SRE) would find this design unusable without a latency model.</p><h3 id="e4-observability-no-debugging-path-for-wrong-routing-decisions" tabindex="-1">E4. Observability: no debugging path for wrong routing decisions <a class="header-anchor" href="#e4-observability-no-debugging-path-for-wrong-routing-decisions" aria-label="Permalink to &quot;E4. Observability: no debugging path for wrong routing decisions&quot;">​</a></h3><p>The design specifies <em>when</em> to route (compaction trigger, consecutive failures, mechanical-mode-confirmed) but not <em>how to know a routing decision was wrong.</em> Concretely:</p><ul><li><strong>No routing log</strong>: There is no specified artifact recording &quot;task X was routed to sidekick at time T because signal S.&quot; Without this, a wrong routing decision (e.g., routing a subtly-complex task to a cost sidekick that produces plausible-but-wrong output) is undetectable after the fact.</li><li><strong>No rollback path</strong>: If a sidekick produces wrong output and the main agent&#39;s &quot;機械重驗&quot; catches it, the design says &quot;升級不重試.&quot; But what about the <em>cost already spent</em> on the wrong sidekick attempt? Is it logged? Attributed? The <code>evolution/cost-log.jsonl</code> exists but the design never references it for Fusion routing audit.</li><li><strong>No A/B framework</strong>: The -35.2% is a simulation, not a measurement. The design does not propose how to <em>measure</em> actual savings once deployed (e.g., run Fusion vs non-Fusion on identical tasks and compare). Without this, the architecture cannot be empirically validated — it can only be <em>believed.</em></li></ul><p>The workspace&#39;s own <code>subagent-strategy.md</code> says &quot;verdict 非證據: 採信前機械重驗.&quot; The design applies this to sidekick <em>output</em> but not to its own <em>routing claims.</em> That&#39;s a consistency gap a same-vendor reviewer (who shares the &quot;trust the architecture&quot; prior) would miss.</p><hr><h2 id="f-implementation-pragmatism" tabindex="-1">F. Implementation Pragmatism <a class="header-anchor" href="#f-implementation-pragmatism" aria-label="Permalink to &quot;F. Implementation Pragmatism&quot;">​</a></h2><h3 id="f1-phase-1-zero-code-change-claim-is-mostly-accurate-but-oversells-one-item" tabindex="-1">F1. Phase 1 &quot;zero-code-change&quot; claim is mostly accurate but oversells one item <a class="header-anchor" href="#f1-phase-1-zero-code-change-claim-is-mostly-accurate-but-oversells-one-item" aria-label="Permalink to &quot;F1. Phase 1 &quot;zero-code-change&quot; claim is mostly accurate but oversells one item&quot;">​</a></h3><p>The GLM validation report is the authoritative check here, and it found: 3/4 optimization items are genuinely zero-modification (✅), 1/4 (checkpoint-based sidekick persistence) needs modification (⚠️). This is a strong, honest validation. The design plan&#39;s §2.3 claim &quot;現有能力,零修改&quot; is <strong>3/4 accurate</strong>. The GLM report correctly downgrades item 4 and correctly flags the ephemeral-environment failure mode (checkpoint is gitignored, so cloud/fresh-clone environments lose sidekick state).</p><p><strong>One gap in the GLM validation</strong>: it does not challenge whether &quot;預設委派&quot; (preset delegation) in optimization item 1 is actually enforceable. The GLM report&#39;s own &quot;non-blocking caveat 3&quot; notes &quot;預設委派是行為紀律非強制 gate&quot; (it&#39;s behavioral discipline, not an enforced gate) and that there&#39;s no PreToolUse hook forcing delegation. This means Phase 1&#39;s headline benefit (route mechanical tasks to sidekick) depends entirely on the main agent <em>choosing</em> to delegate — which, in practice, agents frequently don&#39;t (the &quot;agentic laziness&quot; / &quot;self-preferential bias&quot; failure modes documented in the workspace&#39;s own <code>subagent-strategy.md</code>). Phase 1 is zero-code-change but also zero-enforcement. A cross-vendor reviewer would flag this as &quot;zero-code-change and zero-guarantee.&quot;</p><h3 id="f2-the-agents-md-protocol-draft-1077-bytes-is-too-abstract-to-guide-implementation" tabindex="-1">F2. The AGENTS.md Protocol draft (1077 bytes) is too abstract to guide implementation <a class="header-anchor" href="#f2-the-agents-md-protocol-draft-1077-bytes-is-too-abstract-to-guide-implementation" aria-label="Permalink to &quot;F2. The AGENTS.md Protocol draft (1077 bytes) is too abstract to guide implementation&quot;">​</a></h3><p>Mechanical verification: the draft is 1077 bytes, contains zero model names (grep confirmed: 0 matches). It passes the byte threshold and the L1 zero-model-name rule. But as an <em>implementation guide</em>:</p><ul><li><strong>It describes roles and signals, not mechanisms.</strong> &quot;compaction 觸發 → 評估升降級 model&quot; — <em>how</em> do you evaluate? <em>What</em> is the decision function? The draft defers all of this to &quot;深究 → research/reports/.../fusion-architecture-design-plan.md §2.5,&quot; which itself defers to the Phase 1-3 implementation paths. A reader of the AGENTS.md draft alone cannot implement Fusion.</li><li><strong>It has no failure handling.</strong> The &quot;切換時機&quot; table has &quot;連續失敗 → 升級 sidekick 檔位&quot; but no definition of &quot;連續&quot; (how many? 1? 3?), no definition of &quot;失敗&quot; (crash? wrong output? timeout?), and no path for when the upgrade <em>also</em> fails.</li><li><strong>It is a pointer, not a protocol.</strong> A protocol should be sufficient for two independent implementers to produce compatible behavior. This draft is not — it&#39;s a summary that requires reading the full design plan to act on.</li></ul><p><strong>Verdict</strong>: The draft is a well-formed <em>summary</em> for AGENTS.md&#39;s byte-constrained context, but calling it a &quot;Protocol&quot; overstates its implementability. It would be more accurately titled &quot;Fusion Protocol Summary&quot; or &quot;Fusion Roles &amp; Signals (see design plan for protocol).&quot;</p><h3 id="f3-the-factory-phase-2-config-s-32-doc-urls-information-density-not-padding-—-but-with-a-quality-concern" tabindex="-1">F3. The Factory Phase 2 config&#39;s 32 doc URLs: information density, not padding — but with a quality concern <a class="header-anchor" href="#f3-the-factory-phase-2-config-s-32-doc-urls-information-density-not-padding-—-but-with-a-quality-concern" aria-label="Permalink to &quot;F3. The Factory Phase 2 config&#39;s 32 doc URLs: information density, not padding — but with a quality concern&quot;">​</a></h3><p>Mechanical verification: 32 <code>docs.factory.ai</code> URLs, 36 total URLs. This is high density but not padding — each URL is cited in context next to the configuration step it supports. The GLM report&#39;s structure (step → doc URL → verification → cost impact) is genuinely useful as a runbook.</p><p><strong>However</strong>, the quality concern a cross-vendor reviewer raises: <strong>every URL is Factory&#39;s own documentation</strong>. There are zero independent sources validating Factory Router&#39;s 43% claim, zero independent analyses of Mixed Models compatibility behavior, zero third-party tests of the Session API PATCH semantics. The config guide is a faithful <em>translation of Factory&#39;s docs into step-by-step instructions</em>, but it inherits all of Factory&#39;s self-reporting bias. The guide&#39;s own risk table flags &quot;43% 成本節省 ⚠️ 廠商自報,需獨立驗證&quot; — good — but then the cost impact sections quote the 43% / 81% figures as if established. A cross-vendor reviewer would keep the numbers but consistently label them &quot;vendor-reported&quot; in every occurrence, not just the risk table.</p><hr><h2 id="mechanical-verification-results" tabindex="-1">Mechanical Verification Results <a class="header-anchor" href="#mechanical-verification-results" aria-label="Permalink to &quot;Mechanical Verification Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Expected</th><th>Actual</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>AGENTS.md Protocol draft has zero model names</td><td>0 matches</td><td><code>grep -ciE &#39;opus|sonnet|haiku|fable|glm|kimi|gpt|claude|anthropic|openai|deepseek&#39;</code> = <strong>0</strong></td><td>✅ PASS</td></tr><tr><td>2</td><td>AGENTS.md Protocol draft ≤ 1200 bytes</td><td>≤ 1200</td><td><code>wc -c</code> = <strong>1077</strong></td><td>✅ PASS</td></tr><tr><td>3</td><td>Token simulation Task 3 cost math (existing $0.4613)</td><td>$0.4613</td><td>Python calc = <strong>$0.4613</strong></td><td>✅ PASS</td></tr><tr><td>4</td><td>Token simulation Task 3 cost math (fusion $0.2925, 37%)</td><td>$0.2925, 37%</td><td>Python calc = <strong>$0.2925, 36.6%</strong> (rounds to 37%)</td><td>✅ PASS</td></tr><tr><td>5</td><td>Token simulation Task 5 cost math (existing $1.536)</td><td>$1.536</td><td>Python calc = <strong>$1.5360</strong></td><td>✅ PASS</td></tr><tr><td>6</td><td>Token simulation Task 5 cost math (fusion $0.729, 53%)</td><td>$0.729, 53%</td><td>Python calc = <strong>$0.7290, 52.5%</strong> (rounds to 53%)</td><td>✅ PASS</td></tr><tr><td>7</td><td>Pricing baseline matches model-profiles.md §0/§2.3</td><td>Haiku $1/$5, Sonnet $3/$15, Opus $5/$25, Fable $10/$50</td><td>model-profiles.md lines 113-117 confirm exact match</td><td>✅ PASS</td></tr><tr><td>8</td><td>1.35x ceiling tokenizer factor documented</td><td>documented in §2.3</td><td>model-profiles.md line 120 confirms &quot;ceiling 檔位 tokenizer 較舊版多耗 ~35% token&quot;</td><td>✅ PASS</td></tr><tr><td>9</td><td>Factory Phase 2 config has ≥3 <code>docs.factory.ai</code> URLs (GLM-B acceptance §4.5)</td><td>≥ 3</td><td><code>grep -c</code> = <strong>32</strong></td><td>✅ PASS (far exceeds)</td></tr><tr><td>10</td><td>Design §5.2 &quot;Mid-session 禁止切換模型&quot; rule check</td><td>context-management.md enforces ban</td><td>context-management.md line 3: &quot;Mid-session 禁止切換模型&quot; ✅; <strong>BUT</strong> design&#39;s Factory Phase 3 PATCH switches mid-session — relies on Factory API being an exception to the Claude Code rule. The design claims this is &quot;API 原生支援&quot; but the workspace rule is harness-agnostic in phrasing.</td><td>⚠️ PARTIAL — the Claude Code path complies; the Factory path relies on an implicit &quot;API layer is exempt&quot; reading not explicit in the rule</td></tr><tr><td>11</td><td>Design §5.2 &quot;L1 零模型名&quot; rule check (HARNESS-CORE-v3 §6)</td><td>AGENTS.md Fusion Protocol has zero model names</td><td>Check #1 confirms 0 matches in the draft</td><td>✅ PASS</td></tr><tr><td>12</td><td>Design §5.2 &quot;指揮官不下場&quot; rule check</td><td>delegation-protocol.md §1 enforces</td><td>delegation-protocol.md §1 confirms &quot;預設委派、例外親做&quot; ✅; <strong>BUT</strong> subagent-strategy.md line 9 supersedes this with &quot;預設最簡拓撲；委派須具名效益（非舊「預設委派、例外親做」）&quot; — the design cites the <strong>older, superseded</strong> phrasing</td><td>❌ FAIL — design relies on superseded delegation rule; current rule requires named benefit, not preset delegation</td></tr><tr><td>13</td><td>Design §5.2 &quot;驗證不自驗&quot; rule check</td><td>delegation-protocol.md §6 enforces</td><td>delegation-protocol.md §6 confirms &quot;產出者不得驗收自己的產出&quot;</td><td>✅ PASS</td></tr><tr><td>14</td><td>Devin Fusion 35% / 41% / 88% figures independently verified</td><td>≥1 independent source</td><td>WebSearch returns <strong>only Cognition channels + reposts</strong>; scored article rates evidence 6/10 &quot;廠商自報&quot;</td><td>❌ FAIL — no independent verification exists</td></tr><tr><td>15</td><td>Devin Fusion 57.6 vs 57.0 quality claim has variance/confidence data</td><td>reported or cited</td><td>Not present in design or scored article</td><td>❌ FAIL — 0.6-point delta presented without noise floor</td></tr></tbody></table><hr><h2 id="critical-blind-spots-things-same-vendor-reviewers-would-miss" tabindex="-1">Critical Blind Spots (things same-vendor reviewers would miss) <a class="header-anchor" href="#critical-blind-spots-things-same-vendor-reviewers-would-miss" aria-label="Permalink to &quot;Critical Blind Spots (things same-vendor reviewers would miss)&quot;">​</a></h2><ol><li><p><strong>The -35.2% savings is a workload artifact, not an architecture property.</strong> Same-ecosystem reviewers (who share the &quot;Fusion is good&quot; prior) would accept the headline. A cross-vendor reviewer sees that 84% of the savings (-29.7% of -35.2%) comes from one task type (large migration) that is 10% of the workload by frequency. Remove it and Fusion is a net cost increase. The architecture&#39;s value is contingent on a specific workload shape, not on the architecture itself.</p></li><li><p><strong>The &quot;compaction-time model switch is zero cache penalty&quot; assumption is inherited from Cognition, not verified for Factory.</strong> Same-vendor reviewers trust the Devin Fusion mechanism transfers to Factory&#39;s API. A cross-vendor reviewer asks: does Factory&#39;s post-compaction context survive a model switch intact, or does the new model reprocess the compacted summary from scratch? The design assumes the former; the API docs (D6) describe the field, not the cache behavior.</p></li><li><p><strong>The design relies on the superseded delegation rule.</strong> The workspace&#39;s <code>subagent-strategy.md</code> (current) says &quot;預設最簡拓撲；委派須具名效益&quot; — delegation requires a <em>named benefit</em>, not preset delegation. The design plan and GLM validation both cite <code>delegation-protocol.md</code> §1&#39;s older &quot;預設委派、例外親做.&quot; A same-vendor reviewer reading delegation-protocol.md would not notice the conflict because they share the document&#39;s framing. A cross-vendor reviewer grepping both files finds the contradiction (mechanical check #12).</p></li><li><p><strong>Open-source sidekick partial-failure modes are unaddressed.</strong> Same-vendor reviewers (especially GLM and Kimi, who are themselves the proposed sidekicks) have a structural incentive not to foreground their own failure modes. The &quot;no retry on failure&quot; rule handles crashes but is silent on correct-syntax-wrong-logic and plausible-hallucination — the two failure modes most likely from open-source models on mechanical tasks.</p></li><li><p><strong>Latency and observability are entirely absent.</strong> Same-vendor reviewers focused on cost and quality would not notice the missing dimensions because the design&#39;s framing makes them invisible. A cross-vendor reviewer from a latency-sensitive or ops-debugging background immediately asks &quot;how do I know a routing decision was wrong?&quot; and finds no answer.</p></li><li><p><strong>The verification cost is omitted from the savings figure.</strong> Same-vendor reviewers accept &quot;main agent re-verifies&quot; as a quality mechanism without costing it. A cross-vendor reviewer sees that item-by-item verification by a ceiling-tier main agent is itself a significant cost that, if included, would compress the -35.2% figure.</p></li><li><p><strong>The FrontierCode 57.6-vs-57.0 delta is presented as meaningful without a noise floor.</strong> Same-vendor reviewers familiar with the benchmark would implicitly know the variance but not flag its absence. A cross-vendor reviewer treats any sub-1-point delta on an undocumented-variance benchmark as noise, not evidence.</p></li></ol><hr><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><p><strong>Prioritized by impact on the decision to adopt:</strong></p><ol><li><p><strong>Reframe the headline savings as workload-conditional, not universal.</strong> Replace &quot;-35.2%&quot; with &quot;−35.2% cost-weighted (−2.8% frequency-weighted) on estimated workspace distribution; savings are driven by large-migration tasks and are negative for cross-module refactor and security review.&quot; Do not ship the -35.2% figure without the +2.8% frequency-weighted figure alongside it. <strong>This is the single most important correction.</strong></p></li><li><p><strong>Run <code>evolution/cost-log.jsonl</code> to get real task distribution weights before quoting any aggregate savings.</strong> The simulation admits the weights are &quot;粗估.&quot; The file exists. A 1-hour analysis would replace speculation with measurement and either confirm or invalidate the -35.2% figure for this workspace&#39;s actual workload.</p></li><li><p><strong>Resolve the delegation-rule conflict before implementation.</strong> The design cites the superseded &quot;預設委派、例外親做&quot; (delegation-protocol.md §1). The current rule is &quot;預設最簡拓撲；委派須具名效益&quot; (subagent-strategy.md line 9). Either (a) update delegation-protocol.md to match, or (b) re-anchor the Fusion design to the current rule (each Fusion delegation must name its benefit: context isolation / parallelism / adversarial review / low-risk mechanical volume / noise reduction). Option (b) is more work but more correct.</p></li><li><p><strong>Specify the partial-failure detection mechanism for open-source sidekicks.</strong> &quot;No retry on failure&quot; is insufficient. Add: (a) orthogonal verification method (main agent re-runs grep with a <em>different</em> pattern, not the same one), (b) scope-verification step (main agent confirms the sidekick operated on the intended file(s) before accepting output), (c) citation-existence check for research sidekicks (grep the cited URL, do not trust the sidekick&#39;s claim it exists).</p></li><li><p><strong>Add a latency model, even a rough one.</strong> At minimum: estimate the sidekick round-trip cost (spawn/PATCH + execution + report-back) in wall-clock seconds and compare to inline execution. Explicitly exclude Fusion from latency-sensitive task types (on-call incident response, real-time debugging). The design currently says nothing; saying &quot;Fusion is not recommended for latency-bound tasks&quot; is better than silence.</p></li><li><p><strong>Add a routing log and an A/B measurement plan.</strong> Without <code>evolution/cost-log.jsonl</code> entries recording routing decisions + outcomes, the architecture cannot be empirically validated. Specify: (a) log every Fusion routing decision (task, signal, route chosen, model, cost, outcome), (b) run a 2-week Fusion-vs-non-Fusion A/B on identical task types, (c) report measured savings, not simulated savings. This converts the architecture from &quot;believed&quot; to &quot;verified,&quot; per the workspace&#39;s own &quot;verdict ≠ evidence&quot; principle.</p></li><li><p><strong>Verify the compaction-time model-switch cache behavior empirically on Factory before relying on it.</strong> The &quot;zero cache penalty&quot; claim is the load-bearing assumption. Run one test: a Factory session that PATCHes the model at compaction, and measure whether the post-compaction context is reprocessed from scratch or served from the new model&#39;s cache. If reprocessed, the -35.2% figure needs a cache-miss penalty correction.</p></li><li><p><strong>Cost the verification overhead and include it in the savings figure.</strong> For each task type, add the main agent&#39;s verification token cost (reading sidekick output at ceiling pricing) to the Fusion cost column. This will reduce the task 3/5 savings and deepen the task 2/4 cost increases, producing a more honest net figure.</p></li><li><p><strong>Downgrade the &quot;harness-neutral&quot; claim to &quot;bi-harness (Claude Code + Factory).&quot;</strong> The design does not address pure-API, alternative-harness, or orchestration-layer paths. Calling it &quot;universal&quot; or &quot;harness-neutral&quot; overstates portability. The AGENTS.md §1 portability note already admits &quot;switching to Codex/Cursor = rebuild enforcement layer&quot; — the Fusion design should inherit this caveat explicitly.</p></li><li><p><strong>Rename the AGENTS.md draft from &quot;Fusion Protocol&quot; to &quot;Fusion Protocol Summary&quot; or add a one-line implementability caveat.</strong> As written, it is a pointer to the design plan, not a self-sufficient protocol. A reader who implements only what the draft says will produce an incomplete Fusion.</p></li></ol><hr><h2 id="final-verdict" tabindex="-1">Final Verdict <a class="header-anchor" href="#final-verdict" aria-label="Permalink to &quot;Final Verdict&quot;">​</a></h2><p><strong>SHIP-WITH-CAVEATS</strong></p><p><strong>Rationale</strong>: The architecture is internally coherent, the cost math is mechanically correct, the Phase 1 zero-code-change claim is 3/4 validated honestly by the GLM report, and the Factory Phase 2 config is a genuinely useful runbook. However, the headline -35.2% savings is a workload artifact (driven by one task type representing 10% of frequency) that is presented as if it generalizes; the load-bearing &quot;zero cache penalty at compaction&quot; assumption is inherited from Cognition&#39;s self-reported blog and not verified for Factory&#39;s API; the design relies on a superseded delegation rule; and latency, observability, verification cost, and open-source partial-failure modes are unaddressed. These are fixable with measurement and reframing, not architectural redesign — hence SHIP-WITH-CAVEATS rather than NEEDS-REVISION. The caveats are significant enough that adopting the architecture <em>as currently described</em> without running the recommended measurements (real task weights, compaction cache test, A/B validation) would mean shipping a simulation as if it were a result.</p><p><strong>Confidence level</strong>: <strong>Medium-high</strong> on the findings (mechanical checks passed; rule conflict verified by grep; source-dependency verified by web search; cost math verified by Python). <strong>Medium</strong> on the verdict — the gap between SHIP-WITH-CAVEATS and NEEDS-REVISION depends on whether the workspace owner treats &quot;run the measurements first&quot; as a caveat (ship-with-caveats) or a blocker (needs-revision). I lean ship-with-caveats because the architecture is directionally sound and the fixes are additive (measurement, reframing), not structural. Confidence would rise to High if recommendation #2 (real task weights from cost-log.jsonl) and #7 (compaction cache test) were executed and confirmed the assumptions.</p>',100)])])}const g=t(n,[["render",a]]);export{m as __pageData,g as default};
